"use client";

import { memo, useState, type ComponentProps } from "react";
import { cn } from "cn";
import { Canvas } from "./canvas";
import shader from "./liquid-surface-background.wgsl";
import bloomShader from "./liquid-surface-bloom.wgsl";

const liquidSurfaceBloom = {
  label: "liquid-surface-bloom",
  source: bloomShader,
  uniforms: (_time: number, size: readonly [number, number]) => ({
    bloom: {
      resolution: size,
      threshold: 0.55,
      intensity: 1.4,
      radius: 3.5,
      enabled: 1,
      pad1: 0,
      pad2: 0,
    },
  }),
};

export type LiquidSurfaceBackgroundProps = ComponentProps<"div"> & {
  speed?: number;
  distortion?: number;
  intensity?: number;
  interactive?: boolean;
};

export const LiquidSurfaceBackground = memo(function LiquidSurfaceBackground({
  className,
  children,
  speed = 0.35,
  distortion = 0.8,
  intensity = 1,
  interactive = true,
  onPointerMove,
  onPointerLeave,
  ...props
}: LiquidSurfaceBackgroundProps = {}) {
  const [pointer, setPointer] = useState({ x: 0.5, y: 0.5, hover: 0 });
  const rate = Number.isFinite(speed) ? Math.max(0, speed) : 0.35;
  const warp = Number.isFinite(distortion) ? Math.max(0, Math.min(2, distortion)) : 0.8;
  const brightness = Number.isFinite(intensity) ? Math.max(0, Math.min(2, intensity)) : 1;

  return (
    <div
      {...props}
      data-slot="liquid-surface-background"
      className={cn("relative isolate min-h-96 overflow-hidden bg-background", className)}
      onPointerMove={(event) => {
        onPointerMove?.(event);
        if (!interactive || event.pointerType === "touch") return;
        const bounds = event.currentTarget.getBoundingClientRect();
        if (!bounds.width || !bounds.height) return;
        setPointer({
          x: (event.clientX - bounds.left) / bounds.width,
          y: (event.clientY - bounds.top) / bounds.height,
          hover: 1,
        });
      }}
      onPointerLeave={(event) => {
        onPointerLeave?.(event);
        setPointer({ x: 0.5, y: 0.5, hover: 0 });
      }}
    >
      <Canvas
        aria-label="Animated liquid surface with interactive metallic reflections"
        role="img"
        shader={shader}
        label="liquid-surface-background"
        lightFallback="radial-gradient(ellipse at 30% 20%, #fff 0%, transparent 30%), linear-gradient(135deg, #b8d4e0, #eff7fa 48%, #a3c3cf)"
        fallback="radial-gradient(ellipse at 30% 20%, #edf5ff 0%, transparent 18%), radial-gradient(ellipse at 70% 70%, #315c91 0%, transparent 35%), linear-gradient(135deg, #090b12, #33465e 48%, #0b1019)"
        className="absolute inset-0 -z-10 h-full min-h-0 border-0 bg-transparent"
        animated={rate > 0}
        fps={30}
        postProcess={liquidSurfaceBloom}
        uniforms={(time, size) => ({
          cfg: {
            metrics: [size[0], size[1], time, brightness],
            pointer: [pointer.x, pointer.y, interactive ? pointer.hover : 0, 0],
            settings: [rate, warp, 0.3, 0],
          },
        })}
      />
      {children}
    </div>
  );
});

import { lightCyan, lightSurface, lightViolet } from "./light-palette.shared.wgsl";

struct Theme { mode: vec4f };
@group(1) @binding(0) var<uniform> theme: Theme;

struct Config {
  metrics: vec4f,
  pointer: vec4f,
  settings: vec4f,
};
@group(0) @binding(0) var<uniform> cfg: Config;

fn surfaceHeight(p: vec2f, t: f32, mouse: vec2f) -> f32 {
  var height = sin(p.x * 4.0 + t) * cos(p.y * 4.0 + t * 0.8) * 0.3;
  height += sin(p.x * 8.0 - t * 1.4) * cos(p.y * 7.0 + t * 1.1) * 0.15;
  let distance = length(p - mouse);
  let ripple = sin(distance * 28.0 - t * 8.0) *
    exp(-distance * 4.5 / max(0.1, 0.22)) * cfg.pointer.z * cfg.settings.y * 0.4;
  return height + ripple;
}

@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let aspect = cfg.metrics.x / max(cfg.metrics.y, 1.0);
  let p = (uv - 0.5) * vec2f(aspect, 1.0);
  let mouse = (cfg.pointer.xy - 0.5) * vec2f(aspect, 1.0);
  let time = cfg.metrics.z * cfg.settings.x;
  let epsilon = 0.005;

  let center = surfaceHeight(p, time, mouse);
  let right = surfaceHeight(p + vec2f(epsilon, 0.0), time, mouse);
  let up = surfaceHeight(p + vec2f(0.0, epsilon), time, mouse);
  let normal = normalize(vec3f((center - right) / epsilon, (center - up) / epsilon, 1.0));

  let lightDirection = normalize(vec3f(0.5, 0.8, 0.7));
  let cursorDirection = normalize(vec3f(mouse.x - p.x, mouse.y - p.y, 0.4));
  let viewDirection = vec3f(0.0, 0.0, 1.0);
  let specular = pow(max(0.0, dot(normal, normalize(lightDirection + viewDirection))), 32.0);
  let cursorSpecular = pow(max(0.0, dot(normal, normalize(cursorDirection + viewDirection))), 24.0) * cfg.pointer.z;
  let fresnel = pow(1.0 - max(0.0, dot(normal, viewDirection)), 3.0);
  let rainbow = 0.5 + 0.5 * cos(normal.y * 6.0 + vec3f(0.0, 2.0, 4.0) + time * 0.5);
  let chrome = vec3f(0.1, 0.12, 0.16) + normal.z * 0.2 + rainbow * fresnel * 0.75;
  let vignette = 1.0 - smoothstep(0.4, 1.3, length(p));
  if (theme.mode.x > 0.5) {
    let pearl = mix(lightSurface(), lightCyan(), 0.2) + normal.z * 0.08;
    let iridescence = mix(lightCyan(), lightViolet(), rainbow) * fresnel * 0.24;
    let lightColor = pearl + iridescence + vec3f(specular * 0.25) + vec3f(0.1, 0.18, 0.22) * cursorSpecular;
    return vec4f(clamp(lightColor * (0.85 + vignette * 0.15) * cfg.metrics.w, vec3f(0.0), vec3f(1.0)), 1.0);
  }
  let color = (chrome + vec3f(1.0) * specular * 0.9 + vec3f(0.6, 0.9, 1.0) * cursorSpecular * 1.4) * cfg.metrics.w;
  return vec4f(clamp(color * vignette, vec3f(0.0), vec3f(1.0)), 1.0);
}

struct Theme { mode: vec4f };
@group(1) @binding(0) var<uniform> theme: Theme;

@group(0) @binding(0) var scene: texture_2d<f32>;
@group(0) @binding(1) var sceneSampler: sampler;

struct BloomUniforms {
  resolution: vec2f,
  threshold: f32,
  intensity: f32,
  radius: f32,
  enabled: f32,
  pad1: f32,
  pad2: f32,
};
@group(0) @binding(2) var<uniform> bloom: BloomUniforms;

fn luminance(color: vec3f) -> f32 {
  return dot(color, vec3f(0.2126, 0.7152, 0.0722));
}

fn brightSample(uv: vec2f) -> vec3f {
  let color = textureSample(scene, sceneSampler, uv).rgb;
  let knee = 0.15;
  return color * smoothstep(bloom.threshold - knee, bloom.threshold + knee, luminance(color));
}

@fragment
fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let base = textureSample(scene, sceneSampler, uv);
  if (bloom.enabled < 0.5 || theme.mode.x > 0.5) {
    return base;
  }

  let texel = vec2f(1.0) / bloom.resolution * bloom.radius;
  var glow = brightSample(uv) * 0.22;
  var totalWeight = 0.22;

  let ring1 = array<vec2f, 4>(
    vec2f(-1.0, -1.0),
    vec2f(1.0, -1.0),
    vec2f(-1.0, 1.0),
    vec2f(1.0, 1.0)
  );
  for (var i = 0; i < 4; i++) {
    glow += brightSample(uv + ring1[i] * texel * 1.2) * 0.14;
    totalWeight += 0.14;
  }

  let ring2 = array<vec2f, 4>(
    vec2f(0.0, 2.4),
    vec2f(0.0, -2.4),
    vec2f(2.4, 0.0),
    vec2f(-2.4, 0.0)
  );
  for (var i = 0; i < 4; i++) {
    glow += brightSample(uv + ring2[i] * texel) * 0.09;
    totalWeight += 0.09;
  }

  let diagonal = 4.5 * 0.707;
  let ring3 = array<vec2f, 4>(
    vec2f(-diagonal, -diagonal),
    vec2f(diagonal, -diagonal),
    vec2f(-diagonal, diagonal),
    vec2f(diagonal, diagonal)
  );
  for (var i = 0; i < 4; i++) {
    let offset = ring3[i] * texel;
    let sampleValue = brightSample(uv + offset);
    let red = brightSample(uv + offset * 1.08).r;
    let blue = brightSample(uv + offset * 0.92).b;
    glow += vec3f(red, sampleValue.g, blue) * 0.055;
    totalWeight += 0.055;
  }

  let ring4 = array<vec2f, 4>(
    vec2f(0.0, 7.5),
    vec2f(0.0, -7.5),
    vec2f(7.5, 0.0),
    vec2f(-7.5, 0.0)
  );
  for (var i = 0; i < 4; i++) {
    glow += brightSample(uv + ring4[i] * texel) * 0.03;
    totalWeight += 0.03;
  }

  glow = glow / totalWeight * bloom.intensity * 2.2;
  let combined = base.rgb + glow;
  let toneMapped = combined / (vec3f(1.0) + combined * 0.15);
  return vec4f(toneMapped, base.a);
}

"use client";

import { memo, useEffect, useRef, type ReactNode, type ComponentProps } from "react";
import { useReducedMotion } from "motion/react";
import { createShaderRenderer, type PostProcessOptions } from "./shader-renderer.shared";
import { cn } from "cn";

type RendererOptions = Parameters<typeof createShaderRenderer>[2];
export interface CanvasProps extends ComponentProps<"div"> {
  shader: Parameters<typeof createShaderRenderer>[1];
  label?: string;
  fallback: string;
  lightFallback: string;
  fallbackContent?: ReactNode;
  uniforms: RendererOptions["uniforms"];
  animated?: boolean;
  fps?: number;
  dpr?: number | [number, number];
  postProcess?: PostProcessOptions;
}

/** Shared rendering only; consumers own uniforms and pointer behavior. */
export const Canvas = memo(function Canvas({
  shader,
  label = "shader-canvas",
  fallback,
  lightFallback,
  fallbackContent,
  uniforms,
  animated = true,
  fps = 30,
  dpr = 1,
  postProcess,
  className,
  children,
  ...props
}: CanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const latestUniforms = useRef(uniforms);
  const rendererRef = useRef<ReturnType<typeof createShaderRenderer> | null>(null);
  const reducedMotion = useReducedMotion();
  const minDpr = typeof dpr === "number" ? dpr : dpr[0];
  const maxDpr = typeof dpr === "number" ? dpr : dpr[1];
  useEffect(() => {
    latestUniforms.current = uniforms;
    rendererRef.current?.render();
  }, [uniforms]);
  useEffect(() => {
    if (!canvasRef.current) return;
    const renderer = createShaderRenderer(canvasRef.current, shader, {
      label,
      uniforms: (time, size) => latestUniforms.current(time, size),
      animated: animated && !reducedMotion,
      fps,
      surface: { dpr: minDpr === maxDpr ? minDpr : [minDpr, maxDpr] },
      postProcess,
    });
    rendererRef.current = renderer;
    return () => {
      renderer.dispose();
      rendererRef.current = null;
    };
  }, [shader, label, animated, reducedMotion, fps, minDpr, maxDpr, postProcess]);
  return (
    <div
      {...props}
      data-slot={label}
      className={cn(
        "hangry-background relative isolate min-h-96 overflow-hidden border border-border bg-background",
        className,
      )}
    >
      <div aria-hidden="true" className="pointer-events-none absolute inset-0 -z-10">
        <div className="absolute inset-0 dark:hidden" style={{ backgroundImage: lightFallback }} />
        <div className="absolute inset-0 hidden dark:block">
          <div className="absolute inset-0" style={{ backgroundImage: fallback }} />
          {fallbackContent}
        </div>
        <canvas ref={canvasRef} className="absolute inset-0 block h-full w-full opacity-0" />
      </div>
      {children}
    </div>
  );
});

import {
  effect,
  frame,
  frameLoop,
  init,
  sampler,
  surface,
  target,
  type Frame,
  type SurfaceOptions,
} from "vgpu";

type ShaderSource = Parameters<typeof effect>[1];
type Bindings = Parameters<ReturnType<typeof effect>["set"]>[0];

export interface PostProcessOptions {
  label: string;
  source: ShaderSource;
  uniforms?: (time: number, size: readonly [number, number]) => Bindings;
}

interface ShaderRendererOptions {
  label: string;
  uniforms: (time: number, size: readonly [number, number]) => Bindings;
  animated?: boolean;
  fps?: number;
  surface?: SurfaceOptions;
  postProcess?: PostProcessOptions;
  themeAware?: boolean;
  themeMask?: boolean;
}

/** Owns one canvas effect. Components supply bindings and retain their own input/UI logic. */
export function createShaderRenderer(
  canvas: HTMLCanvasElement,
  source: ShaderSource,
  {
    label,
    uniforms,
    animated = true,
    fps = 60,
    surface: surfaceOptions = { dpr: 1 },
    postProcess,
    themeAware = true,
    themeMask = false,
  }: ShaderRendererOptions,
) {
  let disposed = false;
  let gpu: Awaited<ReturnType<typeof init>> | undefined;
  let output: ReturnType<typeof surface> | undefined;
  let scene: ReturnType<typeof target> | undefined;
  let themeObserver: MutationObserver | undefined;
  let light = themeAware && !document.documentElement.classList.contains("dark");
  const theme = () => ({ mode: [Number(light), Number(themeMask), 0, 0] });
  let sceneSampler: ReturnType<typeof sampler> | undefined;
  let shader: ReturnType<typeof effect> | undefined;
  let postShader: ReturnType<typeof effect> | undefined;
  let loop: ReturnType<typeof frameLoop> | undefined;
  let observer: ResizeObserver | undefined;
  let unsubscribeResize: (() => void) | undefined;
  let pendingFrame = 0;
  let draw: ((currentFrame: Frame) => void) | undefined;
  canvas.style.opacity = "0";

  const dispose = () => {
    if (disposed) return;
    disposed = true;
    loop?.stop();
    observer?.disconnect();
    themeObserver?.disconnect();
    cancelAnimationFrame(pendingFrame);
    unsubscribeResize?.();
    shader?.dispose();
    postShader?.dispose();
    output?.dispose();
    gpu?.dispose();
  };
  const render = () => {
    if (disposed || !draw || animated) return;
    cancelAnimationFrame(pendingFrame);
    pendingFrame = requestAnimationFrame(() => {
      if (!disposed && gpu && draw) frame(gpu, draw);
    });
  };
  const start = async () => {
    const initialized = await init();
    if (disposed) {
      initialized.dispose();
      return;
    }
    gpu = initialized;
    output = surface(gpu, canvas, surfaceOptions);
    scene = postProcess ? target(gpu, { size: output.size }) : undefined;
    sceneSampler = postProcess
      ? sampler(gpu, { minFilter: "linear", magFilter: "linear" })
      : undefined;
    light = themeAware && !document.documentElement.classList.contains("dark");
    shader = effect(gpu, source, {
      label,
      set: { ...uniforms(0, (scene ?? output).size), theme: theme() },
    });
    postShader = postProcess
      ? effect(gpu, postProcess.source, {
          label: postProcess.label,
          set: {
            theme: theme(),
            scene: scene,
            sceneSampler,
            ...postProcess.uniforms?.(0, output.size),
          },
        })
      : undefined;
    await shader.compile(scene ?? output);
    await postShader?.compile(output);
    if (disposed) return;
    const startedAt = performance.now();
    if (output && scene && sceneSampler) {
      unsubscribeResize = output.onResize(({ width, height }) => {
        scene?.resize([width, height]);
        postShader?.set({
          scene,
          sceneSampler,
          ...postProcess?.uniforms?.(0, [width, height]),
        });
      });
    }
    draw = (currentFrame) => {
      if (!output || !shader || disposed) return;
      const time = animated ? (performance.now() - startedAt) / 1000 : 0;
      const renderTarget = scene ?? output;
      shader.set({ ...uniforms(time, renderTarget.size), theme: theme() });
      if (postShader && scene && sceneSampler) {
        postShader.set({
          theme: theme(),
          scene,
          sceneSampler,
          ...postProcess?.uniforms?.(time, output.size),
        });
        currentFrame.pass(scene, shader);
        currentFrame.pass(output, postShader);
      } else {
        currentFrame.pass(scene ?? output, shader);
      }
      canvas.style.opacity = "1";
    };
    if (themeAware) {
      themeObserver = new MutationObserver(() => {
        light = themeAware && !document.documentElement.classList.contains("dark");
        render();
      });
      themeObserver.observe(document.documentElement, {
        attributes: true,
        attributeFilter: ["class"],
      });
    }
    if (animated) loop = frameLoop(gpu, draw, { fps });
    else {
      observer = new ResizeObserver(render);
      observer.observe(canvas);
      render();
    }
  };
  void start().catch((error: unknown) => {
    if (!disposed) {
      canvas.style.opacity = "0";
      console.warn(`${label} could not start; retaining its fallback:`, error);
      dispose();
    }
  });
  return { dispose, render };
}

// Dedicated pigments for light-mode shader materials. No output filtering.
export fn lightPaper() -> vec3f { return vec3f(0.9568627, 0.9803922, 0.9647059); }
export fn lightSurface() -> vec3f { return vec3f(0.8470588, 0.9333333, 0.8862745); }
export fn lightInk() -> vec3f { return vec3f(0.0666667, 0.2352941, 0.1960784); }
export fn lightEmerald() -> vec3f { return vec3f(0.0000000, 0.4862745, 0.3450980); }
export fn lightCyan() -> vec3f { return vec3f(0.0000000, 0.5450980, 0.7215686); }
export fn lightBlue() -> vec3f { return vec3f(0.1568627, 0.3686275, 0.9098039); }
export fn lightViolet() -> vec3f { return vec3f(0.5098039, 0.2666667, 0.8470588); }
export fn lightRose() -> vec3f { return vec3f(0.8392157, 0.2352941, 0.5137255); }
export fn lightGold() -> vec3f { return vec3f(0.8431373, 0.5764706, 0.1137255); }
